GR_ERAS = [
 ("kingdom", "The constitutional kingdom", "1862–1915", 1862, 1915,
  "Otto was deposed in 1862 and the constitution of 1864 gave Greece universal male suffrage, decades ahead of most of Europe. What it did not give was stable government: the king still picked ministries until the 1875 principle of dedilomeni forced him to appoint whoever held the chamber. The parties of the period are named after the men who led them, Trikoupis against Deligiannis, which tells you what they were."),
 ("schism", "The National Schism", "1920–1936", 1916, 1936,
  "Venizelos against the crown, twice over, in a quarrel about which side to take in the First World War that outlived the war by twenty years. Between them sit the Asia Minor catastrophe and a million and a half refugees who changed the electorate permanently, a republic proclaimed in 1924 and abolished in 1935, and a run of elections whose results were repeatedly overturned by coup."),
 ("postwar", "Civil war and its long shadow", "1946–1964", 1937, 1964,
  "The 1946 election was held under a boycott by the left and won by the royalists; the civil war that followed ran to 1949 and its losers stayed banned from politics for a generation. Centre-right governments then held power for fifteen years under electoral systems redrawn to keep them there, until Papandreou's Centre Union broke through in 1963."),
 ("junta", "The colonels", "1967–1974", 1965, 1973,
  "No elections. The colonels seized power in April 1967, weeks before a vote Papandreou was expected to win, and held it for seven years."),
 ("metapolitefsi", "Metapolitefsi", "1974–2009", 1974, 2009,
  "The junta collapsed over Cyprus and Karamanlis returned from Paris to build a republic that lasted. A referendum ended the monarchy, the Communist Party was legalised after twenty-seven years, and from 1981 New Democracy and PASOK alternated in power with reinforced-proportional majorities, a two-party system as settled as any in Europe."),
 ("crisis", "The crisis", "2012–2019", 2010, 2019,
  "The debt crisis destroyed the two-party system in a single cycle. PASOK went from governing party to 12% in three years, Syriza from a fringe to power, and Golden Dawn into parliament. Two elections in 2012 and two in 2015, a referendum that rejected the bailout terms the government then accepted, and a bonus of fifty seats that decided who governed."),
 ("current", "After the crisis", "2023–", 2020, 2100,
  "The bonus was abolished, then restored. May 2023 produced a parliament under the old proportional rules that nobody could govern from, so a second election in June ran under the new rules and handed New Democracy a majority. The left is now split four ways where Syriza stood alone."),
]

